END_ENTITY;

IFCLIBRARYREFERENCE.express:
ENTITY IfcLibraryReference
 SUBTYPE OF (IfcExternalReference);
 INVERSE
	ReferenceIntoLibrary : SET [0:1] OF IfcLibraryInformation FOR LibraryReference;
END_ENTITY;

IFCLIGHTDISTRIBUTIONDATA.express:
