 DERIVE
	VaryingAppliedLoads : LIST [3:?] OF IfcStructuralLoad := IfcAddToBeginOfList(SELF\IfcStructuralActivity.AppliedLoad, SubsequentAppliedLoads);
END_ENTITY;

IFCSTRUCTURALPOINTACTION.express:
